#!/usr/bin/env python3
"""Superseded name: the landing's shape authority is generated by `tools/landing.py`.

The tool was renamed when it became a client of the family machine, because it now carries its
own client manifest in the record it writes. This entry point stays so an older command, a hook
or a document that still names it keeps working, and it calls the one implementation.
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from landing import main  # noqa: E402 - the shim exists to reach this one implementation

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
